 commitFinanceChange=function(student,changes,historyText,payment=null,receiptLedger=null){
  if(!payment||payment.settlesMonthlyFee===false)return commitFinanceBefore.apply(this,arguments);
  if(!guard()||window.APBackupRestoring)return null;
  let saved;
  try{saved=financeSnapshot()}catch(problem){toast(problem.message);return null}
  const latest=saved.students?.find(row=>row.id===student.id);
  if(!latest||latest.dueDate!==student.dueDate||latest.lastPaidAt!==student.lastPaidAt||APBilling.cents(latest.monthlyValue)!==APBilling.cents(student.monthlyValue)){
   toast('A mensalidade mudou. Reabra o Financeiro e tente novamente.');
   return null;
  }
  const replaced=state.payments.filter(row=>row.studentId===student.id&&row.settlesMonthlyFee!==false);
  const replacedIds=new Set(replaced.map(row=>row.id));
  const ledger=receiptLedger||(Array.isArray(state.financeReceiptLedger)?state.financeReceiptLedger:[]);
  const replacedLedger=ledger.filter(row=>replacedIds.has(row.paymentId));
  const documents=[...new Set([...replaced.map(row=>row.receipt?.documentId),...replacedLedger.map(row=>row.documentId)].filter(Boolean))];
  const activeLedger=ledger.filter(row=>!replacedIds.has(row.paymentId));
  // Keep a fixed number of fingerprints so a recent retry cannot apply a second baixa.
  const ledgerByPayment=new Map(replacedLedger.map(row=>[row.paymentId,row]));
  const priorFingerprints=replaced.flatMap(payment=>{
   const row=ledgerByPayment.get(payment.id);
   if(!row)return [];
   return [{hash:row.hash,transactionHash:row.transactionHash},...(row.previous||[])];
  }).filter(row=>row.hash||row.transactionHash).slice(0,2);
  if(priorFingerprints.length){
   const index=activeLedger.findIndex(row=>row.paymentId===payment.id);
   if(index===-1)activeLedger.push({paymentId:payment.id,previous:priorFingerprints});
   else activeLedger[index]={...activeLedger[index],previous:priorFingerprints};
  }
  const payments=state.payments.map(row=>{
   if(!replacedIds.has(row.id))return row;
   // Cash reports use paidAt. Billing uses dueDate to identify the settled installment.
   const {id,studentId,studentName,dueDate,paidAt,amount,paidDatePrecision}=row;
   return {id,studentId,studentName:studentName||student.name,dueDate,paidAt,amount,...(paidDatePrecision?{paidDatePrecision}:{})};
  });
  const candidate={...state,
   students:state.students.map(row=>row.id===student.id?{...row,...changes}:row),
   history:[{id:id(),at:new Date().toISOString(),text:historyText,monthlyPaymentStudentId:student.id},...state.history.filter(row=>row.monthlyPaymentStudentId!==student.id)],
   payments:[payment,...payments],
   financeReceiptLedger:activeLedger
  };
  try{localStorage.setItem(DB_KEY,JSON.stringify(candidate))}
